import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { FaPlus, FaTrash, FaEdit, FaCalendarAlt, FaClock, FaBook, FaUniversity, FaBriefcase, FaUsers, FaCheckCircle, FaCircle } from 'react-icons/fa';

function AcademicLoad() {
  const [items, setItems] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newItem, setNewItem] = useState({
    title: '',
    type: 'exam',
    dueDate: '',
    dueTime: '',
    priority: 'medium',
    completed: false
  });

  useEffect(() => {
    const saved = localStorage.getItem('academicLoad');
    if (saved) setItems(JSON.parse(saved));
  }, []);

  const saveToLocal = (newItems) => {
    setItems(newItems);
    localStorage.setItem('academicLoad', JSON.stringify(newItems));
  };

  const addItem = () => {
    if (newItem.title && newItem.dueDate) {
      const newItems = [...items, { ...newItem, id: Date.now() }];
      saveToLocal(newItems);
      setNewItem({ title: '', type: 'exam', dueDate: '', dueTime: '', priority: 'medium', completed: false });
      setShowAddForm(false);
    }
  };

  const toggleComplete = (id) => {
    const newItems = items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
    saveToLocal(newItems);
  };

  const deleteItem = (id) => {
    const newItems = items.filter(item => item.id !== id);
    saveToLocal(newItems);
  };

  const getTypeIcon = (type) => {
    switch(type) {
      case 'exam': return <FaBook color="#e74c3c" />;
      case 'assignment': return <FaCalendarAlt color="#f39c12" />;
      case 'club': return <FaUsers color="#2ecc71" />;
      case 'work': return <FaBriefcase color="#3498db" />;
      default: return <FaUniversity color="#9b59b6" />;
    }
  };

  const getPriorityColor = (priority) => {
    if (priority === 'high') return '#e74c3c';
    if (priority === 'medium') return '#f39c12';
    return '#2ecc71';
  };

  const upcomingItems = items.filter(i => !i.completed).sort((a,b) => new Date(a.dueDate) - new Date(b.dueDate));
  const completedItems = items.filter(i => i.completed);

  const types = [
    { value: 'exam', label: '📝 Exam', color: '#e74c3c' },
    { value: 'assignment', label: '📄 Assignment', color: '#f39c12' },
    { value: 'club', label: '👥 Club Meeting', color: '#2ecc71' },
    { value: 'work', label: '💼 Work Shift', color: '#3498db' },
    { value: 'other', label: '🎯 Other', color: '#9b59b6' }
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>📚 Academic & Life Load</h1>
          <p style={styles.subtitle}>Track exams, assignments, clubs, and work shifts</p>
          <button onClick={() => setShowAddForm(true)} style={styles.addMainBtn}><FaPlus /> Add Task</button>
        </div>

        {showAddForm && (
          <div style={styles.modal}>
            <div style={styles.modalContent}>
              <h3>Add New Task</h3>
              <input type="text" placeholder="Task title" value={newItem.title} onChange={(e) => setNewItem({...newItem, title: e.target.value})} style={styles.input} />
              
              <select value={newItem.type} onChange={(e) => setNewItem({...newItem, type: e.target.value})} style={styles.select}>
                {types.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
              </select>
              
              <input type="date" value={newItem.dueDate} onChange={(e) => setNewItem({...newItem, dueDate: e.target.value})} style={styles.input} />
              <input type="time" value={newItem.dueTime} onChange={(e) => setNewItem({...newItem, dueTime: e.target.value})} style={styles.input} />
              
              <select value={newItem.priority} onChange={(e) => setNewItem({...newItem, priority: e.target.value})} style={styles.select}>
                <option value="low">🟢 Low Priority</option>
                <option value="medium">🟡 Medium Priority</option>
                <option value="high">🔴 High Priority</option>
              </select>
              
              <div style={styles.modalActions}>
                <button onClick={addItem} style={styles.saveBtn}>Save</button>
                <button onClick={() => setShowAddForm(false)} style={styles.cancelBtn}>Cancel</button>
              </div>
            </div>
          </div>
        )}

        <div style={styles.statsRow}>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{upcomingItems.length}</div>
            <div>Pending Tasks</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{completedItems.length}</div>
            <div>Completed</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{items.length}</div>
            <div>Total Tasks</div>
          </div>
        </div>

        <div style={styles.section}>
          <h2>⏰ Upcoming Tasks</h2>
          {upcomingItems.length === 0 && <p style={styles.empty}>No pending tasks. Great job! 🎉</p>}
          {upcomingItems.map(item => (
            <div key={item.id} style={{...styles.taskCard, borderLeft: `4px solid ${getPriorityColor(item.priority)}`}}>
              <div style={styles.taskLeft}>
                <div onClick={() => toggleComplete(item.id)} style={styles.checkbox}>
                  {item.completed ? <FaCheckCircle color="#2ecc71" size={22} /> : <FaCircle color="#ccc" size={22} />}
                </div>
                <div style={styles.taskIcon}>{getTypeIcon(item.type)}</div>
                <div style={styles.taskDetails}>
                  <h4 style={{textDecoration: item.completed ? 'line-through' : 'none'}}>{item.title}</h4>
                  <p><FaCalendarAlt /> {new Date(item.dueDate).toLocaleDateString()} {item.dueTime && `at ${item.dueTime}`}</p>
                </div>
              </div>
              <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash /></button>
            </div>
          ))}
        </div>

        {completedItems.length > 0 && (
          <div style={styles.section}>
            <h2>✅ Completed Tasks</h2>
            {completedItems.map(item => (
              <div key={item.id} style={{...styles.taskCard, opacity: 0.7, background: '#f0fff0'}}>
                <div style={styles.taskLeft}>
                  <div onClick={() => toggleComplete(item.id)} style={styles.checkbox}>
                    <FaCheckCircle color="#2ecc71" size={22} />
                  </div>
                  <div style={styles.taskIcon}>{getTypeIcon(item.type)}</div>
                  <div style={styles.taskDetails}>
                    <h4 style={{textDecoration: 'line-through'}}>{item.title}</h4>
                    <p><FaCalendarAlt /> Completed</p>
                  </div>
                </div>
                <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash /></button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' },
  content: { maxWidth: '700px', margin: '0 auto', padding: '20px', paddingTop: '80px' },
  header: { textAlign: 'center', marginBottom: '30px', color: 'white' },
  title: { fontSize: '32px', marginBottom: '10px' },
  subtitle: { fontSize: '14px', opacity: 0.9, marginBottom: '15px' },
  addMainBtn: { background: 'rgba(255,255,255,0.2)', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '25px', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '8px' },
  modal: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 },
  modalContent: { background: 'white', borderRadius: '20px', padding: '25px', width: '350px' },
  input: { width: '100%', padding: '10px', marginBottom: '10px', border: '2px solid #e0e0e0', borderRadius: '10px', outline: 'none' },
  select: { width: '100%', padding: '10px', marginBottom: '10px', border: '2px solid #e0e0e0', borderRadius: '10px', outline: 'none' },
  modalActions: { display: 'flex', gap: '10px', marginTop: '15px' },
  saveBtn: { flex: 1, padding: '10px', background: '#2ecc71', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer' },
  cancelBtn: { flex: 1, padding: '10px', background: '#e74c3c', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer' },
  statsRow: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '12px', marginBottom: '20px' },
  statCard: { background: 'white', borderRadius: '15px', padding: '15px', textAlign: 'center' },
  statNumber: { fontSize: '28px', fontWeight: 'bold', color: '#667eea' },
  section: { background: 'white', borderRadius: '20px', padding: '20px', marginBottom: '20px' },
  taskCard: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px', marginBottom: '10px', background: '#f8f9ff', borderRadius: '12px' },
  taskLeft: { display: 'flex', alignItems: 'center', gap: '12px', flex: 1 },
  checkbox: { cursor: 'pointer' },
  taskIcon: { fontSize: '20px' },
  taskDetails: { flex: 1 },
  deleteBtn: { background: 'none', border: 'none', cursor: 'pointer', opacity: 0.6 },
  empty: { textAlign: 'center', color: '#999', padding: '20px' },
};

export default AcademicLoad;
